script.setup:
// PyMCubes ran marching cubes over a gyroid field carved into a sphere (recipe
// pymcubes.gyroid-mesh → mesh.json); the scene uploads the quantized buffers as they are.
const data = await (await fetch(ctx.assets["mesh.json"])).json();
const bytes = (b64) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
const gl = ctx.gl, vao = gl.createVertexArray();
gl.bindVertexArray(vao);
const attribute = (location, array, size, type) => {
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER, array, gl.STATIC_DRAW);
  gl.enableVertexAttribArray(location);
  gl.vertexAttribPointer(location, size, type, true, 0, 0);
};
attribute(0, new Uint16Array(bytes(data.positions).buffer), 3, gl.UNSIGNED_SHORT);
attribute(1, new Int8Array(bytes(data.normals).buffer), 3, gl.BYTE);
attribute(2, bytes(data.shell), 1, gl.UNSIGNED_BYTE);
gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, gl.createBuffer());
gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint32Array(bytes(data.indices).buffer), gl.STATIC_DRAW);
gl.bindVertexArray(null);
const vs = `#version 300 es
layout(location=0) in vec3 a_position; layout(location=1) in vec3 a_normal; layout(location=2) in float a_shell;
uniform mat4 u_mvp, u_model; out vec3 v_n; out vec3 v_p; out vec3 v_world; out float v_shell;
void main(){ vec3 p = a_position * 2.0 - 1.0; v_p = p; v_n = mat3(u_model) * a_normal; v_world = (u_model * vec4(p, 1.0)).xyz;
  v_shell = a_shell; gl_Position = u_mvp * vec4(p, 1.0); }`;
const fs = `#version 300 es
precision highp float;
in vec3 v_n; in vec3 v_p; in vec3 v_world; in float v_shell; out vec4 outColor;
uniform vec3 u_eye; uniform float u_cut; uniform float u_time; uniform vec3 u_outer; uniform vec3 u_inner;
void main(){
  if (v_p.z > u_cut) discard;
  vec3 n = normalize(v_n); vec3 view = normalize(u_eye - v_world);
  if (!gl_FrontFacing) n = -n;
  vec3 light = normalize(vec3(0.6, 0.9, 0.5));
  float diff = max(dot(n, light), 0.0), fill = max(dot(n, normalize(vec3(-0.7, -0.2, -0.6))), 0.0);
  float spec = pow(max(dot(n, normalize(light + view)), 0.0), 48.0);
  float rim = pow(1.0 - max(dot(n, view), 0.0), 3.0);
  vec3 base = mix(u_outer, u_inner, smoothstep(0.0, 0.9, v_shell));
  float bands = 0.5 + 0.5 * sin(length(v_p) * 40.0 - u_time * 2.0);
  base *= 0.85 + 0.15 * bands;
  float ao = mix(0.45, 1.0, 1.0 - v_shell * 0.6);
  vec3 c = base * (0.12 + 0.75 * diff + 0.2 * fill) * ao + spec * 0.55 + rim * 0.35 * u_inner;
  outColor = vec4(pow(c, vec3(0.9)), 1.0);
}`;
const bg = `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
void main(){ vec2 q = v_uv - 0.5; float v = 1.0 - dot(q, q) * 1.6; outColor = vec4(vec3(0.035, 0.04, 0.06) * v + vec3(0.02, 0.018, 0.03), 1.0); }`;
Object.assign(ctx.state, {
  vao, count: data.triangleCount * 3,
  camera: ctx.utils.createOrbitCamera({ distance: 3.4, theta: 0.7, phi: 1.15, fov: 40, near: 0.1, far: 50, minDistance: 1, maxDistance: 15 }),
  p: ctx.utils.createProgram(vs, fs),
  bg: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, bg),
});
ctx.publish("triangles", data.triangleCount);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, { mat4 } = ctx.utils, [w, h] = ctx.resolution;
s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
const model = mat4.multiply(mat4.fromYRotation(ctx.time * u.u_spin), mat4.fromXRotation(0.35));
const mvp = mat4.multiply(s.camera.getViewProjection(w / h), model);
gl.disable(gl.DEPTH_TEST);
ctx.utils.drawFullscreen(s.bg);
gl.enable(gl.DEPTH_TEST);
gl.clear(gl.DEPTH_BUFFER_BIT);
gl.useProgram(s.p);
ctx.utils.setStandardUniforms(s.p);
ctx.utils.setUniforms(s.p, { u_mvp: mvp, u_model: model, u_eye: s.camera.getEye() });
gl.bindVertexArray(s.vao);
gl.drawElements(gl.TRIANGLES, s.count, gl.UNSIGNED_INT, 0);
gl.bindVertexArray(null);
